"""The `retailer_usage` parser (D3 §5.4, §13). Every file is generated by `make_sources` or edited from its output."""

import json
from datetime import date, datetime

import pytest

from energatron.adapters.sources.retailer_usage import RETAILER_USAGE, RetailerUsageParser
from energatron.core.errors import InvalidInputError
from energatron.core.models.catalog import Coverage, SourceInfo, SourceType
from energatron.ports.sources import SourceParser
from tests.fixtures.make_sources import make_retailer_usage_csv
from tests.fixtures.synthetic import SYNTHETIC_ACCOUNT, SYNTHETIC_SERIAL

NAME = "usage_all.csv"
RENAMED = "export.csv"


def usage(months: int = 3, **kw: object) -> bytes:
    return make_retailer_usage_csv(months, **kw)  # type: ignore[arg-type]


def inspect(data: bytes, filename: str = NAME) -> SourceInfo:
    return RETAILER_USAGE.inspect(filename, data)


def reason(data: bytes) -> str:
    with pytest.raises(InvalidInputError) as caught:
        inspect(data)
    value = caught.value.details["reason"]
    assert isinstance(value, str)
    return value


def edit(data: bytes, old: str, new: str) -> bytes:
    text = data.decode("utf-8")
    assert old in text
    return text.replace(old, new, 1).encode("utf-8")


def test_the_parser_is_a_source_parser_for_retailer_usage_version_1() -> None:
    parser: SourceParser = RETAILER_USAGE
    assert isinstance(RETAILER_USAGE, RetailerUsageParser)
    assert parser.source is SourceType.RETAILER_USAGE and parser.version == 1


def test_detect_filename_and_content() -> None:
    for name in (NAME, "My USAGE_ALL.CSV"):
        detection = RETAILER_USAGE.detect(name, usage())
        assert detection is not None and detection.evidence == ("filename", "content")


def test_detect_content_only_filename_only_and_neither() -> None:
    content = RETAILER_USAGE.detect(RENAMED, usage())
    assert content is not None and content.evidence == ("content",)
    filename = RETAILER_USAGE.detect(NAME, b"Description,Date,Amount\r\n")
    assert filename is not None and filename.evidence == ("filename",)
    assert RETAILER_USAGE.detect(RENAMED, b"Description,Date,Amount\r\n") is None
    assert RETAILER_USAGE.detect("usage_all.csv.bak", b"") is None


@pytest.mark.parametrize(
    ("old", "new"),
    [
        ("Account Code,", "Account,"),
        (",Total\r", ",Sum\r"),
        (f"E1 ({SYNTHETIC_SERIAL} - Off Peak)", "E1 Off Peak"),
        (f"E1 ({SYNTHETIC_SERIAL} - Off Peak)", f"e1 ({SYNTHETIC_SERIAL} - Off Peak)"),
    ],
)
def test_detect_rejects_other_headers(old: str, new: str) -> None:
    assert RETAILER_USAGE.detect(RENAMED, edit(usage(), old, new)) is None


def test_detect_drops_a_bom_and_takes_lf() -> None:
    detection = RETAILER_USAGE.detect(RENAMED, b"\xef\xbb\xbf" + usage().replace(b"\r\n", b"\n"))
    assert detection is not None and detection.evidence == ("content",)


def test_detect_needs_only_the_first_64_kib() -> None:
    data = usage(1200)
    assert len(data) > 64 * 1024
    detection = RETAILER_USAGE.detect(NAME, data[: 64 * 1024])
    assert detection is not None and detection.evidence == ("filename", "content")


def test_inspect_an_export() -> None:
    info = inspect(usage(3, blank_last=True))
    assert info.source_ts == datetime(2025, 3, 1)
    assert info.coverage == Coverage(start=date(2025, 1, 1), end=date(2025, 3, 1))
    assert info.extra == {
        "rows": 3,
        "tou_labels": ["Off Peak", "Peak", "Shoulder"],
        "nmi_suffixes": ["E1"],
        "source_ts_from": "content",
    }
    assert info.identifiers == {"account": [SYNTHETIC_ACCOUNT], "meter_serial": [SYNTHETIC_SERIAL]}
    assert info.extension == ".csv"


def test_rows_in_any_order_and_labels_sorted() -> None:
    data = usage(2, labels=("Shoulder", "Peak"), register="B1")
    lines = data.split(b"\r\n")
    data = b"\r\n".join([lines[0], lines[2], lines[1], b""])
    info = inspect(data, RENAMED)
    assert info.source_ts == datetime(2025, 2, 1)
    assert info.extra["tou_labels"] == ["Peak", "Shoulder"]
    assert info.extra["nmi_suffixes"] == ["B1"]


def test_extra_never_holds_an_identifier() -> None:
    text = json.dumps(inspect(usage()).extra)
    assert SYNTHETIC_SERIAL not in text and SYNTHETIC_ACCOUNT not in text


@pytest.mark.parametrize(
    ("old", "new", "expected"),
    [
        (",2025-02-01T00:00:00,", ",2025-02-01T00:00:00,1,", "bad_field_count"),
        (",2025-02-01T00:00:00,", ",2025-02-01,", "bad_datetime"),
        (",2025-02-01T00:00:00,", ",2025-02-30T00:00:00,", "bad_datetime"),
        (",110.000,", ",n/a,", "bad_number"),
        ("Account Code,", "Account,", "bad_header"),
    ],
)
def test_malformed(old: str, new: str, expected: str) -> None:
    assert reason(edit(usage(), old, new)) == expected


def test_a_header_alone_has_no_data() -> None:
    assert reason(usage(0)) == "no_data"


def test_not_utf8() -> None:
    assert reason(usage() + b"\xff\r\n") == "not_utf8"


def test_inspect_drops_a_bom_and_takes_lf() -> None:
    assert inspect(b"\xef\xbb\xbf" + usage().replace(b"\r\n", b"\n")).extra["rows"] == 3
